/* PulseFlow static MVP: UI state + local persistence. External providers are configured in Settings. */
const STORAGE='pulseflow-v1';
const now=()=>new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
const uid=()=>Math.random().toString(36).slice(2,9);
const defaults={logged:false,page:'dashboard',pipelineBoard:'Principal',user:{name:'Mariana Costa',email:'mariana@empresa.com',role:'Administrador'},plan:'Pro',columns:[
 {id:'new',name:'Novo lead',limit:24},{id:'service',name:'Em atendimento',limit:48},{id:'waiting',name:'Aguardando resposta',limit:24},{id:'closed',name:'Fechado',limit:0}
],leads:[
 {id:'l1',name:'Lucas Ferreira',phone:'(11) 98888-2201',origin:'Instagram',interest:'Alta',niche:'Clínica',revenue:'R$ 3.000/mês',stage:'waiting',entered:Date.now()-29*3600000,last:'Gostaria de entender os valores.',lastAt:'há 29 min',status:'Aguardando resposta',discardReason:'',callDone:true,notes:'Quer aumentar agenda de procedimentos. Prefere falar no período da tarde.',messages:[['in','Olá! Vi o anúncio e queria saber mais.', '09:12'],['out','Oi, Lucas! Que bom falar com você. Posso entender um pouco sobre sua clínica?', '09:14'],['in','Gostaria de entender os valores.', '09:16']]},
 {id:'l2',name:'Ana Souza',phone:'(21) 97771-6142',origin:'Anúncio Meta',interest:'Média',niche:'Loja',revenue:'R$ 8.000/mês',stage:'service',entered:Date.now()-5*3600000,last:'Pode me mandar uma proposta?',lastAt:'há 5 min',status:'Em conversa',discardReason:'',callDone:false,notes:'Dona de e-commerce de cosméticos. Pediu proposta pelo WhatsApp.',messages:[['in','Oi, tenho interesse no plano para loja.', '10:20'],['out','Olá, Ana! Perfeito, vou te ajudar a encontrar o melhor plano.', '10:22'],['in','Pode me mandar uma proposta?', '10:23']]},
 {id:'l3',name:'Bruno Lima',phone:'(31) 99600-3100',origin:'Indicação',interest:'Alta',niche:'Barbearia',revenue:'R$ 12.000/mês',stage:'new',entered:Date.now()-2*3600000,last:'Novo contato via indicação',lastAt:'há 2 h',status:'Novo',discardReason:'',callDone:false,notes:'Indicado pelo Pedro. Ainda não houve contato.',messages:[]},
 {id:'l4',name:'Carla Mendes',phone:'(11) 95555-1191',origin:'Site',interest:'Baixa',niche:'Clínica',revenue:'R$ 5.000/mês',board:'Abandonados',stage:'waiting',entered:Date.now()-53*3600000,last:'Vou analisar e te retorno.',lastAt:'há 2 dias',status:'Aguardando resposta',discardReason:'Preço',callDone:true,notes:'Achou o investimento acima do orçamento atual.',messages:[['in','Vou analisar e te retorno.', 'Seg 15:02']]},
 {id:'l5',name:'Rafael Alves',phone:'(11) 90000-1212',origin:'Google',interest:'Alta',niche:'Imobiliária',revenue:'R$ 30.000/mês',stage:'closed',entered:Date.now()-3*86400000,last:'Fechamos, obrigado!',lastAt:'ontem',status:'Cliente',discardReason:'',callDone:true,notes:'Fechamento confirmado.',messages:[['out','Vamos iniciar?', 'Ontem 10:10'],['in','Fechamos, obrigado!', 'Ontem 10:13']]}
],cadence:[{id:'c1',delay:0,unit:'hora',action:'Ligar',text:'Ligação de descoberta para entender necessidade e objetivo.'},{id:'c2',delay:2,unit:'hora',action:'Mensagem',text:'Oi, {nome}! Conseguiu falar comigo? Posso te ajudar a avaliar a melhor opção.'},{id:'c3',delay:1,unit:'dia',action:'Mensagem',text:'{nome}, ficou alguma dúvida sobre como isso se aplica ao seu negócio?'},{id:'c4',delay:3,unit:'dias',action:'Mensagem',text:'Última mensagem por aqui: faz sentido conversarmos 10 min esta semana?'}],reminders:[],notifications:[],integrations:{whatsapp:false,voip:false,calendar:false,crm:false},whatsapp:{number:'',businessName:'',method:'Número cadastrado',verifiedAt:''},ai:{name:'Assistente comercial',niche:'Clínica',tone:'Consultivo',objective:'Qualificar e conduzir para reunião'},templates:{'Clínica':['Olá, {nome}! Vi seu interesse. Posso entender como está sua agenda hoje?','Tenho um horário para uma conversa rápida hoje. Funciona para você?'],'Barbearia':['Fala, {nome}! Posso te mostrar como encher a agenda da barbearia?'],'Loja':['Oi, {nome}! Quer aumentar as vendas recorrentes da sua loja?']}};
let state=JSON.parse(localStorage.getItem(STORAGE)||'null')||structuredClone(defaults);state.integrations={...defaults.integrations,...(state.integrations||{})};state.whatsapp={...defaults.whatsapp,...(state.whatsapp||{})}; let selectedId='l1';
const app=document.querySelector('#app');
const emptyLead={id:'empty',name:'Novo contato',phone:'',origin:'',interest:'Média',niche:'',revenue:'',stage:'new',entered:Date.now(),last:'',lastAt:'',status:'',discardReason:'',callDone:false,notes:'',messages:[]};
function persist(){localStorage.setItem(STORAGE,JSON.stringify(state))} function lead(id=selectedId){return state.leads.find(x=>x.id===id)||state.leads[0]||emptyLead}
function esc(v=''){return String(v).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),3400)}
function stageTime(l){let h=Math.max(0,Math.round((Date.now()-l.entered)/3600000)); return h<24?`${h}h na coluna`:`${Math.floor(h/24)}d na coluna`}
function nav(){let wa=state.integrations.whatsapp&&state.whatsapp.number;return `<aside class="sidebar"><div class="brand"><span class="brand-mark">↗</span>PulseFlow</div><nav class="nav">${[['dashboard','⌂','Visão geral'],['pipeline','▦','Pipeline de leads'],['conversation','◉','Conversas'],['automation','⚡','Automações'],['reminders','◷','Lembretes'],['ai','✦','Agente de IA'],['settings','⚙','Configurações'],['admin','♙','Administração'],['billing','◈','Plano e cobrança']].map(([id,i,l])=>`<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${i}</span>${l}</button>`).join('')}</nav><div class="sidebar-footer"><div class="whatsapp-status"><span class="status-dot ${wa?'':'offline'}"></span><b>WhatsApp ${wa?'cadastrado':'não cadastrado'}</b>${wa?`<small>${esc(state.whatsapp.number)}</small>`:'<small>Adicione seu número para começar</small>'}<button class="sidebar-whatsapp" data-modal="whatsapp-number">${wa?'Trocar número':'Cadastrar número'}</button></div><div class="sidebar-user">${esc(state.user.name)}<br><small>${esc(state.user.role)}</small></div></div></aside>`}
function shell(content,title){return `<div class="shell">${nav()}<section class="main"><header class="topbar"><div class="topbar-title">${title}</div><div class="topbar-actions">${state.page!=='dashboard'?'<button class="btn btn-ghost close-page" data-close-page aria-label="Fechar página e voltar ao painel">× Fechar</button>':''}<button class="icon-btn" id="simulate-reply" aria-label="Simular resposta de cliente">🔔${state.notifications.length?'<i class="notif"></i>':''}</button><button class="avatar" data-page="settings" aria-label="Perfil">${state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</button></div></header>${content}</section></div>`}
function login(){app.innerHTML=`<section class="login"><div class="login-card"><div class="brand"><span class="brand-mark">↗</span>PulseFlow</div><h1>Venda mais sem perder o timing.</h1><p>Seu follow-up inteligente, com contexto e automação em um só lugar.</p><form id="login-form"><div class="field"><label>Email</label><input required type="email" value="mariana@empresa.com" placeholder="voce@empresa.com"></div><div class="field"><label>Senha</label><input required type="password" value="12345678" placeholder="••••••••"></div><button class="btn btn-primary btn-full" type="submit">Entrar no PulseFlow</button></form><div class="login-divider">ou</div><button class="btn btn-ghost btn-full" id="google">G Continuar com Google</button><div class="login-switch">Ainda não possui conta? <button class="link" id="create-account">Criar conta</button></div><div class="free-trial">✓ Teste grátis por 7 dias. Sem cartão.</div></div></section>`; document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();state.logged=true;persist();render()};document.querySelector('#google').onclick=()=>{state.logged=true;persist();toast('Login Google simulado com sucesso.');render()};document.querySelector('#create-account').onclick=()=>toast('Conta de demonstração criada. Você já pode entrar!')}
function dashboard(){let open=state.leads.filter(l=>l.stage!=='closed').length,late=state.leads.filter(l=>l.stage==='waiting'&&Date.now()-l.entered>24*3600000).length;return shell(`<div class="page"><div class="page-heading"><div><h1>Bom dia, ${esc(state.user.name.split(' ')[0])} 👋</h1><p>Acompanhe o que precisa da sua atenção hoje.</p></div><button class="btn btn-primary" data-modal="lead">＋ Novo lead</button></div><div class="quick-actions"><button class="btn btn-soft" data-page="pipeline">Ver pipeline</button><button class="btn btn-soft" data-page="automation">⚡ Configurar automação</button><button class="btn btn-ghost" data-page="conversation">Abrir conversas</button></div><section class="metrics"><div class="metric"><div class="metric-label">🔥 LEADS HOJE</div><div class="metric-value">${state.leads.filter(l=>Date.now()-l.entered<86400000).length}</div><div class="metric-sub">↑ 18% vs. ontem</div></div><div class="metric"><div class="metric-label">💬 CONVERSAS ABERTAS</div><div class="metric-value">${open}</div><div class="metric-sub">3 precisam de ação</div></div><div class="metric"><div class="metric-label">💰 VENDAS FECHADAS</div><div class="metric-value">${state.leads.filter(l=>l.stage==='closed').length}</div><div class="metric-sub">R$ 14.700 este mês</div></div><div class="metric"><div class="metric-label">⏳ SEM RESPOSTA</div><div class="metric-value">${late}</div><div class="metric-sub">Ação recomendada hoje</div></div></section><section class="dashboard-grid"><div class="panel"><div class="panel-header"><h2>Prioridades de hoje</h2><button class="link" data-page="reminders">Ver todas</button></div><div class="activity">${state.leads.filter(l=>l.stage==='waiting'||!l.callDone).slice(0,4).map(l=>`<div class="activity-row"><div class="activity-icon">${l.callDone?'💬':'📞'}</div><div><b>${!l.callDone?'Ligar antes de enviar mensagem para':'Responder'} ${esc(l.name)}</b><span>${esc(l.last)} · ${stageTime(l)}</span></div></div>`).join('')||'<p class="empty">Tudo em dia por aqui.</p>'}</div></div><div class="panel"><h2>Pipeline de conversão</h2><div class="funnel">${state.columns.map((c,i)=>{let n=state.leads.filter(l=>l.stage===c.id).length;return `<div class="funnel-row"><span>${esc(c.name)}</span><div class="bar"><i style="width:${Math.max(8,n*23)}%"></i></div><b>${n}</b></div>`}).join('')}</div></div></section></div>`,'Visão geral')}
function pipeline(){let cols=state.columns.map(c=>{let ls=state.leads.filter(l=>l.stage===c.id);return `<section class="column" data-column="${c.id}"><header class="column-head"><div><div class="column-title">${esc(c.name)} <span class="count">${ls.length}</span></div><div class="column-meta">${c.limit?`Limite: ${c.limit}h`: 'Sem limite'} · <button class="link config-sla" data-col="${c.id}">editar</button></div></div><button class="link" data-page="automation">⚡</button></header><div class="lead-list">${ls.map(l=>`<article class="lead-card" draggable="true" data-lead="${l.id}"><div class="lead-top"><div><div class="lead-name">${esc(l.name)}</div><div class="lead-phone">${esc(l.phone)}</div></div><span class="tag ${l.interest==='Alta'?'hot':''}">${esc(l.interest)}</span></div><p class="lead-message">${esc(l.last)}</p><div><span class="tag source">${esc(l.origin)}</span></div><div class="lead-bottom"><span class="${c.limit&&Date.now()-l.entered>c.limit*3600000?'sla-bad':''}">◷ ${stageTime(l)}</span><button class="link open-lead" data-lead="${l.id}">Responder</button></div></article>`).join('')}</div></section>`}).join('');return shell(`<div class="page"><div class="page-heading"><div><h1>Pipeline de leads</h1><p>Arraste os leads entre etapas. O tempo e as regras de cada coluna são monitorados automaticamente.</p></div><button class="btn btn-primary" data-modal="lead">＋ Novo lead</button></div><div class="pipeline-toolbar"><div class="filter-row"><select class="select-mini" id="origin-filter"><option value="">Todas as origens</option>${[...new Set(state.leads.map(l=>l.origin))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="select-mini" id="interest-filter"><option value="">Todo interesse</option><option>Alta</option><option>Média</option><option>Baixa</option></select></div><button class="btn btn-ghost add-column">＋ Nova coluna</button></div><div class="pipeline">${cols}<button class="btn btn-ghost add-column">＋ Nova coluna</button></div></div>`,'Pipeline de leads')}
function messageHtml(m){return `<div class="message ${m[0]}">${esc(m[1])}<span class="message-time">${esc(m[2])}${m[0]==='out'?' ✓✓':''}</span></div>`}
function advice(l){if(!l.callDone)return ['Ação obrigatória: ligação primeiro','A regra comercial desta operação exige tentar uma ligação antes de qualquer mensagem. Registre a ligação para liberar o envio.'];if(l.messages.length===0)return ['Comece descobrindo a necessidade','Use uma pergunta aberta sobre objetivo, desafio e urgência. Evite apresentar preço antes de qualificar.'];if(l.discardReason)return [`Recuperação: ${l.discardReason}`,`Este lead foi descartado por ${l.discardReason.toLowerCase()}. Programe uma reativação contextual em 30 dias, com novidade ou condição relevante.`];if(l.stage==='waiting')return ['Retome com contexto','Ele perguntou sobre valores. Ofereça uma conversa rápida para mapear o cenário antes de enviar proposta.'];return ['Próximo melhor passo','Confirme o objetivo e proponha um horário específico para ligação ou reunião.'];}
function conversation(){let l=lead(), [title,text]=advice(l);return shell(`<div class="page conversation-layout"><aside class="conversation-list"><h2>Conversas</h2><input class="search" placeholder="Buscar lead" id="chat-search"><div id="conv-list">${state.leads.filter(x=>x.stage!=='closed').map(x=>`<button class="conv-item ${x.id===l.id?'active':''}" data-chat="${x.id}"><span class="conv-avatar">${x.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><span class="conv-content"><b>${esc(x.name)}</b><span>${esc(x.last)}</span></span><em class="conv-time">${esc(x.lastAt)}</em></button>`).join('')}</div></aside><section class="chat"><header class="chat-head"><div class="chat-person"><span class="conv-avatar">${l.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><div><strong>${esc(l.name)}</strong><small>${l.status}</small></div></div><div><button class="btn btn-soft" id="call-lead">📞 Ligar</button><button class="btn btn-ghost" id="automate-lead">⚡ Automatizar</button></div></header><div class="chat-messages" id="messages">${l.messages.map(messageHtml).join('')||'<p class="empty">Nova conversa. Faça a ligação de descoberta antes de enviar uma mensagem.</p>'}</div><div class="template-row">${['Primeiro contato','Follow-up','Fechamento'].map(x=>`<button class="template" data-template="${x}">${x}</button>`).join('')}</div>${!l.callDone?'<div class="call-lock">📞 Ligação obrigatória antes da primeira mensagem. Clique em “Ligar” e registre o resultado.</div>':''}<form class="composer" id="composer"><textarea id="message-input" placeholder="Digite uma mensagem" ${!l.callDone?'disabled':''}></textarea><button class="btn btn-primary" ${!l.callDone?'disabled':''}>Enviar</button></form></section><aside class="tips"><section class="lead-profile"><span class="tag ${l.interest==='Alta'?'hot':''}">${esc(l.interest)} interesse</span><h2>${esc(l.name)}</h2><p>${esc(l.phone)}</p><div class="info-grid"><div><span>Origem</span><br>${esc(l.origin)}</div><div><span>Nicho · faturamento</span><br>${esc(l.niche)} · ${esc(l.revenue)}</div><div><span>Etapa</span><br>${esc(state.columns.find(c=>c.id===l.stage)?.name||'')}</div></div></section><section class="tip-card"><h3>✦ IA: ${title}</h3><p>${text}</p></section><section class="tip-card"><h3>📝 Notas de contexto</h3><textarea class="field notes" id="lead-notes" placeholder="Registre necessidades, objeções e próximos passos">${esc(l.notes)}</textarea><button class="link" id="save-notes">Salvar e analisar</button></section><section class="tip-card"><h3>Próximo passo sugerido</h3><p>${l.stage==='waiting'?'Enviar uma retomada em 2h ou agendar ligação.':'Ligar, entender cenário e marcar uma reunião.'}</p></section></aside></div>`,'Conversas')}
function automation(){let templates=Object.entries(state.templates).map(([n,items])=>`<div class="template-card"><strong>${esc(n)}</strong><p>${esc(items[0])}</p><button class="link use-niche" data-niche="${esc(n)}">Usar no agente</button></div>`).join('');return shell(`<div class="page"><div class="page-heading"><div><h1>Automações e cadências</h1><p>Mensagens com contexto, pausadas automaticamente quando o lead responde.</p></div><button class="btn btn-primary" id="save-cadence">Salvar automação</button></div><div class="automation-tabs"><button class="tab active">Cadência principal</button><button class="tab" data-page="pipeline">Automação por coluna</button><button class="tab" id="recovery-flow">Recuperação de descartados</button><button class="tab" id="remarketing-flow">Remarketing</button><button class="tab" id="abandoned-flow">Abandonados</button></div><div class="automation-grid"><section class="panel"><div class="panel-header"><h2>Sequência: qualificação e follow-up</h2><button class="btn btn-soft" id="add-step">＋ Adicionar etapa</button></div><div class="sequence" id="sequence">${state.cadence.map((s,i)=>`<div class="step" data-step="${s.id}"><span class="step-no">${i+1}</span><div class="step-main"><b>${esc(s.action)} após <input class="delay-input" value="${s.delay}" type="number" min="0"> <select class="delay-unit"><option ${s.unit==='hora'?'selected':''}>hora</option><option ${s.unit==='horas'?'selected':''}>horas</option><option ${s.unit==='dia'?'selected':''}>dia</option><option ${s.unit==='dias'?'selected':''}>dias</option></select></b><span contenteditable="true" class="step-text">${esc(s.text)}</span></div><button class="link remove-step">Remover</button></div>`).join('')}</div><div class="automation-note">✓ Regra ativa: se o cliente responder, a cadência pausa, notifica o vendedor e cria uma tarefa de atendimento.</div></section><aside class="panel"><h2>Templates prontos por nicho</h2><div class="template-list">${templates}</div><button class="btn btn-ghost btn-full" id="new-template">＋ Criar template</button></aside></div></div>`,'Automações')}
function reminders(){let list=state.leads.filter(l=>!l.callDone||l.stage==='waiting'||(Date.now()-l.entered>72*3600000&&l.stage!=='closed')).map(l=>({l,kind:!l.callDone?'Ligação necessária':l.discardReason?'Reativar lead descartado':'Lead sem resposta',desc:!l.callDone?'Ligue antes de enviar qualquer mensagem.':l.discardReason?`Motivo: ${l.discardReason}. Janela de recuperação: 30 dias.`:`${stageTime(l)} · cadência pausada aguardando ação.`}));return shell(`<div class="page"><div class="page-heading"><div><h1>Lembretes</h1><p>Nenhum cliente fica esquecido: regras, tarefas e reativações reunidas aqui.</p></div><button class="btn btn-ghost" id="generate-reminders">Atualizar regras</button></div><div class="panel"><div class="panel-header"><h2>Ações para hoje (${list.length})</h2><span class="tag hot">Prioridade inteligente</span></div><div class="reminder-list">${list.map(x=>`<div class="reminder"><span class="reminder-icon">${x.kind==='Ligação necessária'?'📞':'⏳'}</span><div class="reminder-copy"><b>${x.kind}: ${esc(x.l.name)}</b><span>${esc(x.desc)}</span></div><button class="btn btn-primary open-lead" data-lead="${x.l.id}">Responder agora</button></div>`).join('')||'<p class="empty">Tudo certo. Nenhuma ação pendente.</p>'}</div></div></div>`,'Lembretes')}
function aiPage(){let a=state.ai;return shell(`<div class="page"><div class="page-heading"><div><h1>Agente de IA</h1><p>Configure um especialista por negócio. Ele usa conversas e notas para sugerir o próximo passo.</p></div><button class="btn btn-primary" id="save-ai">Salvar agente</button></div><div class="dashboard-grid"><section class="panel"><h2>Configuração do agente</h2><div class="field"><label>Nome do agente</label><input id="ai-name" value="${esc(a.name)}"></div><div class="field"><label>Nicho atendido</label><select id="ai-niche">${['Clínica','Barbearia','Loja','Imobiliária','Personalizado'].map(n=>`<option ${a.niche===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Tom de voz</label><select id="ai-tone">${['Consultivo','Direto','Amigável','Premium'].map(n=>`<option ${a.tone===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Objetivo</label><textarea id="ai-objective">${esc(a.objective)}</textarea></div></section><aside class="panel"><h2>O que o agente observa</h2><div class="activity"><div class="activity-row"><div class="activity-icon">💬</div><div><b>Conversas completas</b><span>Identifica intenção, objeções, urgência e estágio.</span></div></div><div class="activity-row"><div class="activity-icon">📝</div><div><b>Notas do vendedor</b><span>Usa detalhes para sugerir ligação, reunião ou mensagem.</span></div></div><div class="activity-row"><div class="activity-icon">⏱</div><div><b>Tempo em etapa</b><span>Alerta antes do SLA e sugere recuperação contextual.</span></div></div></div><div class="automation-note">Os dados ficam no seu ambiente até integrar o provedor de IA pela API.</div></aside></div></div>`,'Agente de IA')}
function settings(){return shell(`<div class="page"><div class="page-heading"><div><h1>Configurações</h1><p>Conecte seus canais e defina como sua operação funciona.</p></div></div><div class="settings-layout"><nav class="settings-tabs"><button class="active">🔌 Integrações</button><button>👤 Perfil</button><button data-page="billing">💳 Plano</button><button>🔒 Segurança</button></nav><section class="panel"><h2>Integrações</h2><p style="color:var(--muted);font-size:12px">Conectores prontos para receber credenciais e webhooks. Use um provedor oficial de WhatsApp Business para produção.</p>${[['whatsapp','◉','WhatsApp Business','Cloud API / QR Code'],['voip','☎','VoIP','Ligações e registro de tentativas'],['calendar','▣','Google Agenda','Reuniões e lembretes'],['crm','▤','CRM externo','HubSpot, Pipedrive, RD Station e API genérica']].map(([id,icon,name,sub])=>`<div class="integration"><div class="integration-logo">${icon}</div><div class="integration-copy"><b>${name}</b><span>${sub}</span></div><span class="${state.integrations[id]?'connected':''}">${state.integrations[id]?'● Conectado':'Não conectado'}</span><button class="btn ${state.integrations[id]?'btn-ghost':'btn-primary'} connect" data-integration="${id}">${state.integrations[id]?'Configurar':'Conectar'}</button></div>`).join('')}<div class="automation-note">Webhooks esperados: <code>message.received</code>, <code>call.completed</code>, <code>meeting.created</code>. Ao receber resposta, a API deve pausar a automação e gerar notificação.</div></section></div></div>`,'Configurações')}
function admin(){let fields=['Usuários e papéis','Regras globais','Dados e auditoria'];return shell(`<div class="page"><div class="page-heading"><div><h1>Administração</h1><p>Visão restrita à conta administradora.</p></div><button class="btn btn-primary" id="invite-user">＋ Convidar usuário</button></div><div class="admin-grid">${fields.map((x,i)=>`<section class="admin-card"><h3>${x}</h3><p>${['Gerencie vendedores, gestores e permissões de acesso à operação.','Defina SLA padrão, regra de ligação inicial, reativação e cadências.','Exporte leads e acompanhe alterações relevantes da equipe.'][i]}</p><button class="btn btn-soft" data-admin="${i}">${['Gerenciar equipe','Configurar regras','Abrir auditoria'][i]}</button></section>`).join('')}</div><section class="panel" style="margin-top:18px"><h2>Equipe</h2><table class="table"><thead><tr><th>Usuário</th><th>Função</th><th>Status</th></tr></thead><tbody><tr><td>${esc(state.user.name)}<br><small>${esc(state.user.email)}</small></td><td><span class="role">Administrador</span></td><td class="success">● Ativo</td></tr><tr><td>João Vendas<br><small>joao@empresa.com</small></td><td>Vendedor</td><td class="success">● Ativo</td></tr></tbody></table></section></div>`,'Administração')}
function billing(){return shell(`<div class="page billing"><div class="page-heading"><div><h1>Plano e cobrança</h1><p>Seu plano atual: <b>${esc(state.plan)}</b></p></div></div><div class="plans"><section class="plan"><h2>Básico</h2><div class="price">R$ 47<span style="font-size:13px">/mês</span></div><ul><li>Até 500 leads</li><li>Pipeline personalizável</li><li>Templates por nicho</li><li>WhatsApp via API</li></ul><button class="btn btn-ghost btn-full choose-plan" data-plan="Básico">Assinar básico</button></section><section class="plan featured"><span class="tag">Recomendado</span><h2>Pro</h2><div class="price">R$ 97<span style="font-size:13px">/mês</span></div><ul><li>Leads ilimitados</li><li>Automação avançada</li><li>Agente de IA por nicho</li><li>VoIP, agenda e CRM</li></ul><button class="btn btn-primary btn-full choose-plan" data-plan="Pro">Assinar Pro</button></section></div></div>`,'Plano e cobrança')}
function modal(type,data={}){let html='';if(type==='lead')html=`<h2>Novo lead</h2><p>Crie o lead e inicie a cadência certa para ele.</p><form id="new-lead"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>WhatsApp</label><input name="phone" required placeholder="(11) 99999-9999"></div><div class="field"><label>Origem</label><input name="origin" required placeholder="Instagram, anúncio, indicação..."></div><div class="field"><label>Interesse</label><select name="interest"><option>Alta</option><option>Média</option><option>Baixa</option></select></div><div class="field"><label>Nicho e faturamento</label><input name="niche" placeholder="Ex.: Clínica · R$ 10.000/mês"></div><div class="field"><label>Observação</label><textarea name="notes"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`;else if(type==='column')html=`<h2>Nova coluna</h2><p>Defina o estágio e o prazo máximo para agir.</p><form id="new-column"><div class="field"><label>Nome da coluna</label><input name="name" required placeholder="Ex.: Proposta enviada"></div><div class="field"><label>Tempo limite (horas)</label><input type="number" name="limit" value="24" min="0"></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Criar coluna</button></div></form>`;else if(type==='call')html=`<h2>Registrar ligação</h2><p>Registrar libera o envio e alimenta as recomendações da IA.</p><form id="call-form"><div class="field"><label>Resultado</label><select name="result"><option>Não atendeu</option><option>Conversa realizada</option><option>Reunião agendada</option></select></div><div class="field"><label>Notas da ligação</label><textarea name="note" placeholder="O que foi entendido nesta tentativa?"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Registrar ligação</button></div></form>`;else if(type==='connect')html=`<h2>Conectar ${data.name}</h2><p>Informe os dados do provedor. Nesta demonstração a conexão é simulada; em produção, o backend deve guardar credenciais criptografadas e validar webhooks.</p><form id="connect-form" data-int="${data.id}"><div class="field"><label>URL / ID da conta</label><input required placeholder="https://api.seu-provedor.com"></div><div class="field"><label>Chave de API</label><input type="password" required placeholder="••••••••"></div>${data.id==='whatsapp'?'<div class="field"><label>Telefone conectado</label><input placeholder="+55 11 99999-9999"></div>':''}<div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Validar e conectar</button></div></form>`;else if(type==='recovery')html=`<h2>Cadência de recuperação</h2><p>Use motivo do descarte, nicho, produto e faturamento para recuperar leads com contexto.</p><div class="field"><label>Janela para recontato</label><select><option>30 dias após descarte</option><option>45 dias após descarte</option><option>60 dias após descarte</option></select></div><div class="field"><label>Mensagem contextual</label><textarea>Oi, {nome}! Quando conversamos, {motivo}. Tenho uma atualização que pode fazer sentido para seu negócio ({nicho}). Vale retomarmos?</textarea></div><div class="modal-actions"><button class="btn btn-primary close-modal">Ativar recuperação</button></div>`; app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal">${html}</section></div>`)}
function render(){if(!state.logged)return login();let page={dashboard,pipeline,conversation,automation,reminders,ai:aiPage,settings,admin,billing}[state.page]||dashboard;app.innerHTML=page();bind()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;persist();render()});document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>modal(b.dataset.modal));document.querySelectorAll('.open-lead,.conv-item').forEach(b=>b.onclick=e=>{e.stopPropagation();selectedId=b.dataset.lead||b.dataset.chat;state.page='conversation';persist();render()});document.querySelector('#simulate-reply')?.addEventListener('click',()=>simulateReply());document.querySelectorAll('.add-column').forEach(b=>b.onclick=()=>modal('column'));document.querySelectorAll('.config-sla').forEach(b=>b.onclick=()=>{let c=state.columns.find(x=>x.id===b.dataset.col),val=prompt(`Tempo limite na coluna “${c.name}” (em horas):`,c.limit);if(val!==null&&!isNaN(val)){c.limit=+val;persist();render()}});document.querySelectorAll('.lead-card').forEach(card=>{card.ondragstart=()=>card.classList.add('dragging');card.ondragend=()=>card.classList.remove('dragging')});document.querySelectorAll('.column').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('column-drop')};col.ondragleave=()=>col.classList.remove('column-drop');col.ondrop=e=>{e.preventDefault();let card=document.querySelector('.lead-card.dragging');if(card){let l=lead(card.dataset.lead);l.stage=col.dataset.column;l.entered=Date.now();l.status=state.columns.find(c=>c.id===l.stage).name;persist();toast(`${l.name} movido para ${l.status}.`);render()}}});document.querySelector('#composer')?.addEventListener('submit',sendMessage);document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{let el=document.querySelector('#message-input');if(el)el.value=templateText(b.dataset.template,lead())});document.querySelector('#call-lead')?.addEventListener('click',()=>modal('call'));document.querySelector('#automate-lead')?.addEventListener('click',()=>{state.page='automation';persist();render();toast('Cadência aberta para configuração.')});document.querySelector('#save-notes')?.addEventListener('click',()=>{lead().notes=document.querySelector('#lead-notes').value;persist();toast('Notas salvas. IA atualizou a recomendação.')});document.querySelector('#add-step')?.addEventListener('click',()=>{state.cadence.push({id:uid(),delay:1,unit:'dia',action:'Mensagem',text:'Nova mensagem de follow-up'});persist();render()});document.querySelectorAll('.remove-step').forEach(b=>b.onclick=()=>{state.cadence=state.cadence.filter(s=>s.id!==b.closest('.step').dataset.step);persist();render()});document.querySelector('#save-cadence')?.addEventListener('click',saveCadence);document.querySelectorAll('.use-niche').forEach(b=>b.onclick=()=>{state.ai.niche=b.dataset.niche;persist();toast(`Agente configurado para ${b.dataset.niche}.`)});document.querySelectorAll('#recovery-flow,#remarketing-flow,#abandoned-flow').forEach(b=>b.onclick=()=>modal('recovery'));document.querySelector('#generate-reminders')?.addEventListener('click',()=>toast('Regras verificadas: lembretes atualizados.'));document.querySelector('#save-ai')?.addEventListener('click',()=>{state.ai={name:document.querySelector('#ai-name').value,niche:document.querySelector('#ai-niche').value,tone:document.querySelector('#ai-tone').value,objective:document.querySelector('#ai-objective').value};persist();toast('Agente de IA salvo com sucesso.')});document.querySelectorAll('.connect').forEach(b=>b.onclick=()=>{let id=b.dataset.integration;modal('connect',{id,name:{whatsapp:'WhatsApp Business',voip:'VoIP',calendar:'Google Agenda',crm:'CRM externo'}[id]})});document.querySelector('#invite-user')?.addEventListener('click',()=>toast('Convite preparado. Integre seu provedor de e-mail para envio real.'));document.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>toast('Área administrativa em demonstração.'));document.querySelectorAll('.choose-plan').forEach(b=>b.onclick=()=>{state.plan=b.dataset.plan;persist();toast(`Plano ${state.plan} selecionado.`);render()});document.querySelector('#chat-search')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.conv-item').forEach(x=>x.classList.toggle('hidden',!x.textContent.toLowerCase().includes(q)));});bindModal()}
function bindModal(){let m=document.querySelector('#modal');if(!m)return;m.onclick=e=>{if(e.target===m)m.remove()};m.querySelectorAll('.close-modal').forEach(b=>b.onclick=()=>m.remove());m.querySelector('#new-lead')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),n=f.get('niche').split('·');state.leads.unshift({id:uid(),name:f.get('name'),phone:f.get('phone'),origin:f.get('origin'),interest:f.get('interest'),niche:(n[0]||'Não informado').trim(),revenue:(n[1]||'Não informado').trim(),stage:'new',entered:Date.now(),last:'Novo lead cadastrado',lastAt:'agora',status:'Novo lead',discardReason:'',callDone:false,notes:f.get('notes'),messages:[]});persist();m.remove();toast('Lead criado. A regra de ligação foi adicionada.');render()});m.querySelector('#new-column')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);state.columns.push({id:uid(),name:f.get('name'),limit:+f.get('limit')});persist();m.remove();render();toast('Coluna e SLA criados.')});m.querySelector('#call-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),l=lead();l.callDone=true;l.notes+=(l.notes?'\n':'')+`Ligação (${f.get('result')}): ${f.get('note')}`;persist();m.remove();toast('Ligação registrada. Envio de mensagens liberado.');render()});m.querySelector('#connect-form')?.addEventListener('submit',e=>{e.preventDefault();state.integrations[e.currentTarget.dataset.int]=true;persist();m.remove();toast('Integração validada e conectada (modo demonstração).');render()})}
function templateText(kind,l){let maps={'Primeiro contato':`Oi, ${l.name}! Vi seu interesse e quero entender melhor o seu momento. Posso te ligar rapidamente?`,'Follow-up':`Oi, ${l.name}! Retomando nossa conversa: conseguiu avaliar? Posso tirar alguma dúvida e entender o que faz mais sentido para você.`,'Fechamento':`${l.name}, faz sentido agendarmos 10 minutos para fechar os próximos passos?`};return maps[kind]}
function sendMessage(e){e.preventDefault();let el=document.querySelector('#message-input'),text=el.value.trim(),l=lead();if(!text)return;l.messages.push(['out',text,now()]);l.last=text;l.lastAt='agora';el.value='';persist();render();setTimeout(()=>{let msg=document.querySelector('#messages');if(msg)msg.scrollTop=msg.scrollHeight},10)}
function simulateReply(){let l=lead();if(!l){toast('Abra uma conversa para simular uma resposta.');return}let text='Oi! Sim, podemos conversar. Qual horário você tem disponível?';l.messages.push(['in',text,now()]);l.last=text;l.lastAt='agora';l.status='Respondeu agora';state.notifications.unshift({lead:l.id,text:`${l.name} respondeu à sua mensagem`});persist();toast(`Nova resposta de ${l.name}. Cadência pausada e vendedor avisado.`);if(state.page==='conversation')render()}
function saveCadence(){document.querySelectorAll('.step').forEach(row=>{let s=state.cadence.find(x=>x.id===row.dataset.step);s.delay=+row.querySelector('.delay-input').value;s.unit=row.querySelector('.delay-unit').value;s.text=row.querySelector('.step-text').textContent.trim()});persist();toast('Cadência salva e ativa.');}
const createModal=modal;
modal=function(type,data={}){createModal(type,data);bindModal()};
document.addEventListener('click',e=>{if(e.target.closest('[data-close-page]')){state.page='dashboard';persist();render();toast('Página fechada. Você voltou ao painel.')}});
const dashboardBase=dashboard;
dashboard=function(){
  const wa=state.integrations.whatsapp&&state.whatsapp.number;
  const setup=wa
    ? `<section class="whatsapp-setup connected-card"><div class="whatsapp-setup-icon">✓</div><div><strong>WhatsApp cadastrado</strong><p>${esc(state.whatsapp.businessName||'Número principal')} · ${esc(state.whatsapp.number)}</p></div><button class="btn btn-ghost" data-modal="whatsapp-number">Alterar número</button><button class="link" data-page="settings">Configuração avançada</button></section>`
    : `<section class="whatsapp-setup"><div class="whatsapp-setup-icon">◉</div><div><strong>Cadastre seu WhatsApp para começar</strong><p>Informe apenas o número e o nome da empresa. API, QR Code e webhooks ficam nas configurações avançadas.</p></div><button class="btn btn-primary" data-modal="whatsapp-number">Cadastrar número</button></section>`;
  return dashboardBase().replace('<div class="quick-actions">',setup+'<div class="quick-actions">');
};

settings=function(){
  const wa=state.integrations.whatsapp&&state.whatsapp.number;
  const otherIntegrations=[['voip','☎','VoIP','Ligações e registro de tentativas'],['calendar','▣','Google Agenda','Reuniões e lembretes'],['crm','▤','CRM externo','HubSpot, Pipedrive, RD Station e API genérica']];
  return shell(`<div class="page"><div class="page-heading"><div><h1>Configurações</h1><p>As opções técnicas e integrações avançadas ficam reunidas aqui.</p></div></div><div class="settings-layout"><nav class="settings-tabs"><button class="active">🔌 Integrações</button><button>👤 Perfil</button><button data-page="billing">💳 Plano</button><button>🔒 Segurança</button></nav><section class="settings-stack"><div class="panel whatsapp-account"><div class="panel-header"><div><h2>Seu número do WhatsApp</h2><p class="settings-description">Cadastro simples usado em toda a operação.</p></div><span class="connection-pill ${wa?'online':'offline'}">${wa?'● Cadastrado':'● Pendente'}</span></div>${wa?`<div class="registered-number"><span class="integration-logo">◉</span><div><b>${esc(state.whatsapp.businessName||'WhatsApp principal')}</b><strong>${esc(state.whatsapp.number)}</strong><small>Cadastrado em ${esc(state.whatsapp.verifiedAt||'agora')}</small></div></div>`:'<div class="empty-number">Nenhum número cadastrado. Você também pode fazer isso diretamente pelo Dashboard.</div>'}<button class="btn ${wa?'btn-ghost':'btn-primary'}" data-modal="whatsapp-number">${wa?'Alterar número':'Cadastrar número agora'}</button></div><details class="panel advanced-settings" open><summary><span><b>Configuração avançada do WhatsApp</b><small>API oficial, QR Code, credenciais e webhooks</small></span><span>⌄</span></summary><div class="advanced-content"><p class="settings-description">Use esta área somente quando precisar conectar um provedor oficial ou automatizar mensagens reais.</p><div class="advanced-grid"><div><span>Provedor</span><b>Meta Cloud API / BSP</b></div><div><span>Método</span><b>${esc(state.whatsapp.method||'Número cadastrado')}</b></div><div><span>Webhook de entrada</span><b>message.received</b></div><div><span>Status da API</span><b>${state.integrations.whatsapp?'Pronto para configurar':'Não configurado'}</b></div></div><div class="advanced-actions"><button class="btn btn-primary connect" data-integration="whatsapp">Configurar API oficial</button><button class="btn btn-ghost" id="show-qr">Exibir QR Code</button><button class="btn btn-ghost" id="copy-webhook">Copiar webhook</button></div></div></details><div class="panel"><h2>Outras integrações avançadas</h2>${otherIntegrations.map(([id,icon,name,sub])=>`<div class="integration"><div class="integration-logo">${icon}</div><div class="integration-copy"><b>${name}</b><span>${sub}</span></div><span class="${state.integrations[id]?'connected':''}">${state.integrations[id]?'● Conectado':'Não conectado'}</span><button class="btn ${state.integrations[id]?'btn-ghost':'btn-primary'} connect" data-integration="${id}">${state.integrations[id]?'Configurar':'Conectar'}</button></div>`).join('')}<div class="automation-note">Webhooks esperados: <code>message.received</code>, <code>call.completed</code>, <code>meeting.created</code>. Ao receber uma resposta, a automação é pausada e o vendedor é notificado.</div></div></section></div></div>`,'Configurações');
};

const modalBase=modal;
modal=function(type,data={}){
  if(type!=='whatsapp-number')return modalBase(type,data);
  const wa=state.whatsapp||defaults.whatsapp;
  app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal"><div class="simple-connect-head"><span class="whatsapp-setup-icon">◉</span><div><h2>${wa.number?'Alterar WhatsApp':'Cadastrar WhatsApp'}</h2><p>Cadastre o número usado pela sua equipe. A parte técnica pode ser configurada depois.</p></div></div><form id="whatsapp-number-form"><div class="field"><label>Nome da empresa</label><input name="businessName" value="${esc(wa.businessName)}" required placeholder="Ex.: Clínica Mariana"></div><div class="field"><label>Número com DDD</label><input name="number" value="${esc(wa.number)}" required inputmode="tel" pattern="[0-9()+ .-]{10,20}" placeholder="(11) 99999-9999"><small class="field-help">Use um número que possa receber o código de confirmação.</small></div><div class="simple-info">🔒 O número fica salvo na sua conta. Tokens, QR Code e webhooks não aparecem neste cadastro rápido.</div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Salvar número</button></div></form></section></div>`);
  bindModal();
  document.querySelector('#whatsapp-number-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const number=String(f.get('number')).trim();const digits=number.replace(/\D/g,'');if(digits.length<10||digits.length>15){toast('Informe um número válido com DDD.');return}state.whatsapp={...state.whatsapp,businessName:String(f.get('businessName')).trim(),number,verifiedAt:new Date().toLocaleDateString('pt-BR')};state.integrations.whatsapp=true;persist();document.querySelector('#modal')?.remove();render();toast('WhatsApp cadastrado com sucesso.');});
};

const bindBase=bind;
bind=function(){
  bindBase();
  document.querySelector('#show-qr')?.addEventListener('click',()=>toast('QR Code disponível ao concluir a configuração da API oficial.'));
  document.querySelector('#copy-webhook')?.addEventListener('click',()=>toast('Webhook: /api/webhooks/whatsapp'));
};

function columnConfigDefaults(column={}){
  const id=column.id||'custom';
  const observerText=id==='new'?'Identificar urgência, perfil, intenção e dados que faltam para o primeiro contato.':id==='waiting'?'Detectar silêncio, objeções, sentimento e o melhor contexto para retomar.':id==='closed'?'Acompanhar sinais de expansão, renovação ou risco sem iniciar contato automático.':'Resumir a conversa, objeções, próximos passos e mudanças de intenção.';
  const operatorText=id==='new'?'Criar tarefa de ligação e preparar perguntas de descoberta.':id==='waiting'?'Preparar uma retomada contextual com objetivo de abrir conversa, ligação ou reunião.':id==='closed'?'Sugerir oportunidades futuras sem enviar mensagens automaticamente.':'Sugerir a próxima ação e conduzir o lead para uma reunião ou decisão.';
  return {active:true,color:id==='new'?'#635bff':id==='service'?'#2563eb':id==='waiting'?'#f59e0b':id==='closed'?'#16a34a':'#64748b',aiObserver:{enabled:id!=='closed',instructions:observerText},aiOperator:{enabled:id==='service'||id==='waiting',mode:'Executar com aprovação',instructions:operatorText},automations:{callFirst:id==='new',followUp:id==='waiting',pauseOnReply:true,notifySeller:id!=='closed',autoMove:false,targetStage:''}};
}
state.columns=state.columns.map(column=>{const d=columnConfigDefaults(column);return {...d,...column,aiObserver:{...d.aiObserver,...(column.aiObserver||{})},aiOperator:{...d.aiOperator,...(column.aiOperator||{})},automations:{...d.automations,...(column.automations||{})}}});
state.leads.forEach(item=>{if(item.contractValue==null)item.contractValue=0;if(item.product==null)item.product='';if(item.contractStatus==null)item.contractStatus='Não informado';if(item.nextAction==null)item.nextAction='Ligação';if(item.nextDate==null)item.nextDate=''});
persist();

function activeAutomationCount(column){return Object.entries(column.automations||{}).filter(([key,value])=>key!=='targetStage'&&value===true).length}
function money(value){return Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0})}
function noteInsight(item){if(!item.notes&& !item.contractValue)return 'Registre necessidade, objeções e valor estimado. A IA usará esses dados para sugerir a próxima ação.';if(item.contractStatus==='Fechado')return `Contrato de ${money(item.contractValue)} fechado. Preserve o contexto para renovação e expansão.`;if(item.contractValue>0)return `Oportunidade de ${money(item.contractValue)} em ${item.contractStatus.toLowerCase()}. Próximo passo recomendado: ${item.nextAction.toLowerCase()}.`;return 'Há contexto salvo, mas falta o valor do contrato. Complete esse dado para priorizar a oportunidade.'}

const operationalDashboardBase=dashboard;
dashboard=function(){
  const observed=state.columns.filter(column=>column.aiObserver.enabled).length;
  const operated=state.columns.filter(column=>column.aiOperator.enabled).length;
  const automations=state.columns.reduce((total,column)=>total+activeAutomationCount(column),0);
  const contractTotal=state.leads.reduce((total,item)=>total+Number(item.contractValue||0),0);
  const late=state.leads.filter(item=>{const column=state.columns.find(c=>c.id===item.stage);return column?.limit&&Date.now()-item.entered>column.limit*3600000}).length;
  const operations=`<section class="operations-overview"><div class="section-heading"><div><h2>Painel operacional</h2><p>Todos os parâmetros que fazem o follow-up funcionar, sem virar um CRM.</p></div><button class="btn btn-ghost" data-page="pipeline">Configurar no Pipeline</button></div><div class="operations-metrics"><div><span>IA observando</span><strong>${observed}/${state.columns.length} etapas</strong></div><div><span>IA operando</span><strong>${operated}/${state.columns.length} etapas</strong></div><div><span>Automações ativas</span><strong>${automations} regras</strong></div><div><span>Contratos informados</span><strong>${money(contractTotal)}</strong></div><div><span>SLA em risco</span><strong class="${late?'danger-text':''}">${late} leads</strong></div><div><span>Integrações</span><strong>${Object.values(state.integrations).filter(Boolean).length}/4 conectadas</strong></div></div><div class="column-parameters">${state.columns.map(column=>`<button class="column-parameter column-config" data-col="${column.id}" style="--column-color:${column.color}"><span><i></i><b>${esc(column.name)}</b></span><small>${column.limit?`SLA ${column.limit}h`:'Sem SLA'} · Observa ${column.aiObserver.enabled?'sim':'não'} · Opera ${column.aiOperator.enabled?'sim':'não'} · ${activeAutomationCount(column)} automações</small><em>Configurar →</em></button>`).join('')}</div></section>`;
  return operationalDashboardBase().replace('<section class="dashboard-grid">',operations+'<section class="dashboard-grid">');
};

pipeline=function(){
  const columns=state.columns.map(column=>{const items=state.leads.filter(item=>item.stage===column.id);return `<section class="column" data-column="${column.id}" style="--column-color:${column.color}"><header class="column-head"><div><div class="column-title"><i class="column-color"></i>${esc(column.name)} <span class="count">${items.length}</span></div><div class="column-meta">${column.limit?`Limite: ${column.limit}h`:'Sem limite'} · ${column.active?'Ativa':'Pausada'}</div></div><button class="column-settings column-config" data-col="${column.id}" aria-label="Configurar coluna ${esc(column.name)}">⚙</button></header><div class="column-agents"><span class="agent-chip ${column.aiObserver.enabled?'on':''}" title="IA observadora">◉ Observa</span><span class="agent-chip ${column.aiOperator.enabled?'on':''}" title="IA operadora">✦ Opera</span><span class="agent-chip ${activeAutomationCount(column)?'on':''}">⚡ ${activeAutomationCount(column)}</span></div><div class="lead-list">${items.map(item=>`<article class="lead-card" draggable="true" data-lead="${item.id}" data-origin="${esc(item.origin)}" data-interest="${esc(item.interest)}"><div class="lead-top"><div><div class="lead-name">${esc(item.name)}</div><div class="lead-phone">${esc(item.phone)}</div></div><span class="tag ${item.interest==='Alta'?'hot':''}">${esc(item.interest)}</span></div><p class="lead-message">${esc(item.last)}</p><div class="lead-tags"><span class="tag source">${esc(item.origin)}</span>${item.contractValue?`<span class="tag contract-tag">${money(item.contractValue)}</span>`:''}</div>${item.notes?`<p class="lead-note-preview">📝 ${esc(item.notes.split('\n')[0])}</p>`:''}<div class="lead-timing"><span class="${column.limit&&Date.now()-item.entered>column.limit*3600000?'sla-bad':''}">◷ ${stageTime(item)}</span></div><div class="lead-actions"><button class="link lead-notes" data-lead="${item.id}">Notas e contrato</button><button class="link open-lead" data-lead="${item.id}">Responder</button></div></article>`).join('')||'<div class="column-empty">Nenhum lead nesta etapa</div>'}</div></section>`}).join('');
  return shell(`<div class="page"><div class="page-heading"><div><h1>Pipeline de execução</h1><p>Cada etapa combina SLA, IA observadora, IA operadora e automações próprias.</p></div><button class="btn btn-primary" data-modal="lead">＋ Novo lead</button></div><div class="pipeline-toolbar"><div class="filter-row"><select class="select-mini" id="origin-filter"><option value="">Todas as origens</option>${[...new Set(state.leads.map(item=>item.origin))].map(value=>`<option>${esc(value)}</option>`).join('')}</select><select class="select-mini" id="interest-filter"><option value="">Todo interesse</option><option>Alta</option><option>Média</option><option>Baixa</option></select></div><button class="btn btn-ghost add-column">＋ Nova coluna</button></div><div class="pipeline">${columns}<button class="btn btn-ghost add-column">＋ Nova coluna</button></div></div>`,'Pipeline de execução');
};

function columnForm(column,isNew=false){
  const config=column||columnConfigDefaults({});
  const targets=state.columns.filter(item=>item.id!==config.id).map(item=>`<option value="${item.id}" ${config.automations?.targetStage===item.id?'selected':''}>${esc(item.name)}</option>`).join('');
  return `<div class="modal-title-row"><div><h2>${isNew?'Nova coluna':`Configurar ${esc(config.name)}`}</h2><p>Defina o comportamento da etapa. Observar analisa; operar executa ou sugere ações.</p></div><span class="column-config-icon">⚙</span></div><form id="column-config-form" data-col="${isNew?'':config.id}"><div class="config-section compact-fields"><div class="field"><label>Nome da coluna</label><input name="name" required value="${isNew?'':esc(config.name)}" placeholder="Ex.: Proposta enviada"></div><div class="field"><label>Cor</label><input name="color" type="color" value="${config.color||'#635bff'}"></div><div class="field"><label>Tempo limite (horas)</label><input name="limit" type="number" min="0" value="${config.limit??24}"></div><label class="switch-row"><input type="checkbox" name="active" ${config.active?'checked':''}><span><b>Etapa ativa</b><small>Recebe leads e executa regras</small></span></label></div><div class="config-section"><div class="config-section-head"><span class="ai-role observer">◉</span><div><h3>IA observadora</h3><p>Analisa conversas e notas, identifica intenção, risco e dados faltantes. Nunca envia mensagens.</p></div><label class="toggle"><input type="checkbox" name="observerEnabled" ${config.aiObserver?.enabled?'checked':''}><span></span></label></div><div class="field"><label>O que deve observar nesta etapa</label><textarea name="observerInstructions">${esc(config.aiObserver?.instructions||'')}</textarea></div></div><div class="config-section"><div class="config-section-head"><span class="ai-role operator">✦</span><div><h3>IA operadora</h3><p>Prepara ou executa o próximo passo de acordo com o nível de autonomia.</p></div><label class="toggle"><input type="checkbox" name="operatorEnabled" ${config.aiOperator?.enabled?'checked':''}><span></span></label></div><div class="field"><label>Nível de autonomia</label><select name="operatorMode">${['Somente sugerir','Executar com aprovação','Automático'].map(mode=>`<option ${config.aiOperator?.mode===mode?'selected':''}>${mode}</option>`).join('')}</select></div><div class="field"><label>Objetivo e instruções da IA operadora</label><textarea name="operatorInstructions">${esc(config.aiOperator?.instructions||'')}</textarea></div></div><div class="config-section"><h3>Automações desta coluna</h3><div class="automation-checks"><label><input type="checkbox" name="callFirst" ${config.automations?.callFirst?'checked':''}><span><b>Ligar primeiro</b><small>Bloqueia mensagem até registrar ligação</small></span></label><label><input type="checkbox" name="followUp" ${config.automations?.followUp?'checked':''}><span><b>Cadência de follow-up</b><small>Executa a sequência ativa desta etapa</small></span></label><label><input type="checkbox" name="pauseOnReply" ${config.automations?.pauseOnReply?'checked':''}><span><b>Pausar ao responder</b><small>Interrompe envios quando o cliente responde</small></span></label><label><input type="checkbox" name="notifySeller" ${config.automations?.notifySeller?'checked':''}><span><b>Avisar vendedor</b><small>Cria alerta quando houver ação humana</small></span></label><label><input type="checkbox" name="autoMove" ${config.automations?.autoMove?'checked':''}><span><b>Mover automaticamente</b><small>Move após concluir a ação da etapa</small></span></label></div><div class="field"><label>Destino da movimentação automática</label><select name="targetStage"><option value="">Selecione uma etapa</option>${targets}</select></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">${isNew?'Criar coluna':'Salvar configuração'}</button></div></form>`;
}

function leadWorkspace(item){return `<div class="modal-title-row"><div><h2>${esc(item.name)}</h2><p>Contexto operacional do lead — sem duplicar o cadastro completo do seu CRM.</p></div><span class="column-config-icon">📝</span></div><form id="lead-workspace-form" data-lead="${item.id}"><div class="workspace-tabs"><span class="active">Notas e contexto</span><span>Contrato</span><span>Próxima ação</span></div><div class="ai-note-analysis"><b>✦ Leitura da IA</b><p>${esc(noteInsight(item))}</p></div><div class="config-section"><h3>Notas e contexto</h3><div class="field"><label>O que a IA e o vendedor precisam lembrar</label><textarea name="notes" rows="5" placeholder="Necessidade, objeção, decisores e próximos passos">${esc(item.notes)}</textarea></div></div><div class="contract-grid config-section"><div><h3>Contrato</h3><div class="field"><label>Produto ou serviço</label><input name="product" value="${esc(item.product)}" placeholder="Ex.: Plano Pro"></div><div class="field"><label>Preço do contrato (R$)</label><input name="contractValue" type="number" min="0" step="0.01" value="${item.contractValue||''}" placeholder="0,00"></div><div class="field"><label>Status comercial</label><select name="contractStatus">${['Não informado','Em negociação','Proposta enviada','Fechado'].map(status=>`<option ${item.contractStatus===status?'selected':''}>${status}</option>`).join('')}</select></div></div><div><h3>Próxima ação</h3><div class="field"><label>Tipo</label><select name="nextAction">${['Ligação','Mensagem','Reunião','Aguardar cliente'].map(action=>`<option ${item.nextAction===action?'selected':''}>${action}</option>`).join('')}</select></div><div class="field"><label>Data e hora</label><input name="nextDate" type="datetime-local" value="${esc(item.nextDate)}"></div><div class="context-rule">A regra de ligação continua valendo: quando ativa na coluna, ligue antes de enviar mensagem.</div></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Salvar e atualizar IA</button></div></form>`}

const workspaceModalBase=modal;
modal=function(type,data={}){
  if(type!=='column'&&type!=='column-config'&&type!=='lead-workspace')return workspaceModalBase(type,data);
  let html='';
  if(type==='column')html=columnForm({...columnConfigDefaults({}),id:uid(),name:'',limit:24},true);
  if(type==='column-config')html=columnForm(state.columns.find(item=>item.id===data.id));
  if(type==='lead-workspace'){const item=lead(data.id);if(item.contractValue==null)item.contractValue=0;if(item.product==null)item.product='';if(item.contractStatus==null)item.contractStatus='Não informado';if(item.nextAction==null)item.nextAction='Ligação';if(item.nextDate==null)item.nextDate='';html=leadWorkspace(item)}
  app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal modal-wide">${html}</section></div>`);
  bindModal();
  document.querySelector('#column-config-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const values=new FormData(form);const existing=state.columns.find(item=>item.id===form.dataset.col);const base=existing||{id:uid(),...columnConfigDefaults({})};const updated={...base,name:String(values.get('name')).trim(),color:String(values.get('color')),limit:Number(values.get('limit')||0),active:values.has('active'),aiObserver:{enabled:values.has('observerEnabled'),instructions:String(values.get('observerInstructions')).trim()},aiOperator:{enabled:values.has('operatorEnabled'),mode:String(values.get('operatorMode')),instructions:String(values.get('operatorInstructions')).trim()},automations:{callFirst:values.has('callFirst'),followUp:values.has('followUp'),pauseOnReply:values.has('pauseOnReply'),notifySeller:values.has('notifySeller'),autoMove:values.has('autoMove'),targetStage:String(values.get('targetStage')||'')}};if(existing)Object.assign(existing,updated);else state.columns.push(updated);persist();document.querySelector('#modal')?.remove();render();toast(existing?'Coluna configurada com sucesso.':'Nova coluna criada e configurada.');});
  document.querySelector('#lead-workspace-form')?.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(event.currentTarget);const item=lead(event.currentTarget.dataset.lead);item.notes=String(values.get('notes')).trim();item.product=String(values.get('product')).trim();item.contractValue=Number(values.get('contractValue')||0);item.contractStatus=String(values.get('contractStatus'));item.nextAction=String(values.get('nextAction'));item.nextDate=String(values.get('nextDate')||'');persist();document.querySelector('#modal')?.remove();render();toast('Notas, contrato e próxima ação atualizados.');});
};

const workspaceBindBase=bind;
bind=function(){
  workspaceBindBase();
  document.querySelectorAll('.column-config').forEach(button=>button.onclick=()=>modal('column-config',{id:button.dataset.col}));
  document.querySelectorAll('.lead-notes').forEach(button=>button.onclick=event=>{event.stopPropagation();modal('lead-workspace',{id:button.dataset.lead})});
  const applyPipelineFilters=()=>{const origin=document.querySelector('#origin-filter')?.value||'',interest=document.querySelector('#interest-filter')?.value||'';document.querySelectorAll('.lead-card').forEach(card=>card.classList.toggle('hidden',Boolean(origin&&card.dataset.origin!==origin||interest&&card.dataset.interest!==interest)))};
  document.querySelector('#origin-filter')?.addEventListener('change',applyPipelineFilters);
  document.querySelector('#interest-filter')?.addEventListener('change',applyPipelineFilters);
};

