/* Autenticação real e administração global multiempresa. */
if(state.authVersion!==2){state.authVersion=2;state.logged=false;state.user={name:'',email:'',role:''};persist()}
async function authCall(action,options={}){
  const response=await fetch(`/api/auth?action=${action}`,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});
  const value=await response.json();
  if(!response.ok)throw new Error(value.error||'Não foi possível concluir.');
  return value;
}
login=function(mode='login'){
  const register=mode==='register';
  app.innerHTML=`<section class="login"><div class="login-card"><div class="brand"><span class="brand-mark">↗</span>PulseFlow</div><h1>${register?'Crie sua conta':'Entre no PulseFlow'}</h1><p>${register?'Configure sua empresa e comece em poucos minutos.':'Acesse sua operação ou a administração da plataforma.'}</p><form id="real-auth-form" data-mode="${mode}">${register?'<div class="field"><label>Seu nome</label><input name="name" required></div><div class="field"><label>Empresa</label><input name="company" required></div>':''}<div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" required autocomplete="current-password"></div><p class="auth-error" id="auth-error"></p><button class="btn btn-primary btn-full" type="submit">${register?'Criar conta e começar':'Entrar'}</button></form><div class="login-switch">${register?'Já possui conta?':'Ainda não possui conta?'} <button class="link" id="auth-switch">${register?'Entrar':'Criar conta'}</button></div><div class="free-trial">✓ Plano Base por R$ 9,90/mês · teste grátis por 7 dias.</div></div></section>`;
  document.querySelector('#auth-switch').onclick=()=>login(register?'login':'register');
  document.querySelector('#real-auth-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"]'),error=document.querySelector('#auth-error'),values=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent='Entrando...';error.textContent='';try{const result=await authCall(register?'register':'login',{method:'POST',body:JSON.stringify(values)});state.logged=true;state.user={...state.user,...result.user};state.plan=result.user.role==='super_admin'?'Admin':'Base';state.page=result.user.role==='super_admin'?'platform-admin':'dashboard';if(result.user.organization_id)await loadOwnWorkspace(result.user);persist();render()}catch(problem){error.textContent=problem.message;button.disabled=false;button.textContent=register?'Criar conta e começar':'Entrar'}};
};

function platformAdminPage(){return shell(`<div class="page platform-admin"><div class="page-heading"><div><span class="eyebrow">ADMINISTRAÇÃO GLOBAL</span><h1>Contas e usuários</h1><p>Acesse e mantenha todo o ambiente de cada cliente com auditoria.</p></div><button class="btn btn-ghost" id="refresh-platform-admin">Atualizar</button></div><section class="metrics" id="platform-summary"><div class="metric"><div class="metric-label">EMPRESAS</div><div class="metric-value">—</div></div><div class="metric"><div class="metric-label">USUÁRIOS</div><div class="metric-value">—</div></div><div class="metric"><div class="metric-label">ATIVOS</div><div class="metric-value">—</div></div></section><section class="panel"><div class="panel-header"><h2>Empresas</h2><span class="tag" id="accounts-count">Carregando</span></div><div class="admin-table-wrap"><table class="table"><thead><tr><th>Empresa</th><th>Plano</th><th>Nicho</th><th>Usuários</th><th>Status</th><th>Ações</th></tr></thead><tbody id="platform-accounts"><tr><td colspan="6">Carregando banco...</td></tr></tbody></table></div></section><section class="panel" style="margin-top:16px"><div class="panel-header"><h2>Todos os usuários</h2><input class="search admin-search" id="platform-user-search" placeholder="Buscar usuário ou empresa"></div><div class="admin-table-wrap"><table class="table"><thead><tr><th>Usuário</th><th>Empresa</th><th>Função</th><th>Último acesso</th><th>Status</th></tr></thead><tbody id="platform-users"><tr><td colspan="5">Carregando banco...</td></tr></tbody></table></div></section></div>`,'Admin global')}
async function loadPlatformAdmin(){
  const accountsBody=document.querySelector('#platform-accounts'),usersBody=document.querySelector('#platform-users');if(!accountsBody)return;
  try{const data=await authCall('admin');document.querySelector('#platform-summary').innerHTML=[['EMPRESAS',data.summary.accounts],['USUÁRIOS',data.summary.users],['ATIVOS',data.summary.active]].map(([label,value])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div></div>`).join('');document.querySelector('#accounts-count').textContent=`${data.accounts.length} contas`;accountsBody.innerHTML=data.accounts.map(item=>`<tr><td><b>${esc(item.name)}</b><br><small>${new Date(item.created_at).toLocaleDateString('pt-BR')}</small></td><td>${esc(item.plan)}</td><td>${esc(item.niche||'Não informado')}</td><td>${item.users_count}</td><td class="${item.status==='active'?'success':'danger'}">● ${item.status==='active'?'Ativa':'Suspensa'}</td><td><div class="admin-account-actions"><button class="btn btn-soft support-account" data-org="${item.id}" data-name="${esc(item.name)}">Acessar tudo</button><button class="link account-status" data-org="${item.id}" data-status="${item.status==='active'?'suspended':'active'}">${item.status==='active'?'Suspender':'Reativar'}</button></div></td></tr>`).join('')||'<tr><td colspan="6">Nenhuma empresa cadastrada.</td></tr>';usersBody.innerHTML=data.users.map(item=>`<tr class="platform-user-row"><td><b>${esc(item.name)}</b><br><small>${esc(item.email)}</small></td><td>${esc(item.organization_name||'PulseFlow')}</td><td><span class="role">${esc(item.role)}</span></td><td>${item.last_login_at?new Date(item.last_login_at).toLocaleString('pt-BR'):'Nunca'}</td><td class="success">● ${esc(item.status)}</td></tr>`).join('')}catch(error){accountsBody.innerHTML=`<tr><td colspan="6">${esc(error.message)}</td></tr>`;usersBody.innerHTML='<tr><td colspan="5">Não foi possível carregar usuários.</td></tr>'}
}
const platformNavBase=nav;
nav=function(){if(state.user.role!=='super_admin'||state.support?.active)return platformNavBase().replace('</aside>',state.support?.active?'<button class="sidebar-logout exit-support">← Voltar ao ADM</button></aside>':'<button class="sidebar-logout" data-logout>Sair da conta</button></aside>');return `<aside class="sidebar"><div class="brand"><span class="brand-mark">↗</span>PulseFlow <span class="tag">ADM</span></div><nav class="nav"><button data-page="platform-admin" class="active"><span class="nav-icon">♙</span>Contas e usuários</button></nav><div class="sidebar-footer">Administrador global<br><small>${esc(state.user.email)}</small></div><button class="sidebar-logout" data-logout>Sair da conta</button></aside>`};
const platformBindBase=bind;
bind=function(){platformBindBase();document.querySelector('#refresh-platform-admin')?.addEventListener('click',loadPlatformAdmin);document.querySelector('#platform-user-search')?.addEventListener('input',event=>{const query=event.target.value.toLowerCase();document.querySelectorAll('.platform-user-row').forEach(row=>row.classList.toggle('hidden',!row.textContent.toLowerCase().includes(query)))});document.querySelectorAll('.support-account').forEach(button=>button.onclick=()=>openSupportAccount(button.dataset.org,button.dataset.name));document.querySelectorAll('.account-status').forEach(button=>button.onclick=async()=>{await authCall('admin-account',{method:'POST',body:JSON.stringify({organization_id:button.dataset.org,status:button.dataset.status})});toast(button.dataset.status==='active'?'Conta reativada.':'Conta suspensa.');loadPlatformAdmin()});document.querySelectorAll('.exit-support').forEach(button=>button.onclick=exitSupport);document.querySelector('[data-logout]')?.addEventListener('click',async()=>{try{await authCall('logout',{method:'POST',body:'{}'})}finally{state.logged=false;state.user={name:'',email:'',role:''};state.page='dashboard';persist();render()}})};
const platformRenderBase=render;
render=function(){if(state.logged&&state.user.role==='super_admin'&&!state.support?.active){state.page='platform-admin';app.innerHTML=platformAdminPage();bind();loadPlatformAdmin();return}platformRenderBase();if(state.support?.active)document.querySelector('.main')?.insertAdjacentHTML('afterbegin',`<div class="support-banner"><b>Modo suporte: ${esc(state.support.name)}</b><span>Alterações ficam registradas na auditoria.</span><button class="exit-support">Voltar ao ADM</button></div>`);document.querySelectorAll('.exit-support').forEach(button=>button.onclick=exitSupport)};
render();
if(state.logged)authCall('me').then(async result=>{state.user={...state.user,...result.user};if(result.user.organization_id)await loadOwnWorkspace(result.user);persist();render()}).catch(()=>{state.logged=false;state.user={name:'',email:'',role:''};persist();render()});

function freshWorkspace(){const clean=structuredClone(defaults);clean.leads=[];clean.reminders=[];clean.notifications=[];clean.whatsapp=structuredClone(defaults.whatsapp);clean.integrations=structuredClone(defaults.integrations);return clean}
function operationalState(){const {logged,user,authVersion,page,support,plan,...workspace}=state;return workspace}
let workspaceSaveTimer;
async function loadOwnWorkspace(user){const data=await authCall(`workspace&organization_id=${encodeURIComponent(user.organization_id)}`);const identity={logged:true,user:{...state.user,...user},authVersion:state.authVersion,page:state.page,plan:data.account.plan};Object.assign(state,data.workspace||freshWorkspace(),identity)}
async function openSupportAccount(organizationId,name){const data=await authCall(`workspace&organization_id=${encodeURIComponent(organizationId)}`);const identity={logged:true,user:state.user,authVersion:state.authVersion,page:'dashboard',plan:'Admin',support:{active:true,orgId:organizationId,name}};Object.assign(state,data.workspace||freshWorkspace(),identity);persist();render();toast(`Modo suporte aberto para ${name}.`)}
function exitSupport(){state.support={active:false};state.page='platform-admin';state.plan='Admin';persist();render()}
const browserPersist=persist;
persist=function(){browserPersist();const organizationId=state.support?.active?state.support.orgId:state.user?.organization_id;if(!state.logged||!organizationId)return;clearTimeout(workspaceSaveTimer);workspaceSaveTimer=setTimeout(()=>authCall('workspace',{method:'POST',body:JSON.stringify({organization_id:organizationId,state:operationalState()})}).catch(()=>toast('Não foi possível sincronizar esta alteração.')),500)};

/* Operação manual sem API: ligação inicial + dez mensagens, sempre aprovadas pelo vendedor. */
const manualMessageSteps=[
  [2,'horas','Oi, {nome}! Obrigado pelo interesse. Posso entender o que você busca hoje?'],
  [1,'dia','{nome}, conseguiu ver minha mensagem? Se preferir, posso te explicar em uma ligação rápida.'],
  [2,'dias','Quero entender seu momento antes de sugerir qualquer coisa. Qual é seu principal objetivo agora?'],
  [3,'dias','Separei uma ideia que pode fazer sentido para o seu cenário. Posso te mostrar em 10 minutos?'],
  [5,'dias','{nome}, existe alguma dúvida ou prioridade que eu ainda não entendi?'],
  [7,'dias','Posso te enviar um exemplo prático de como isso funcionaria no seu negócio?'],
  [10,'dias','Se ainda fizer sentido, tenho dois horários para conversarmos: hoje à tarde ou amanhã de manhã.'],
  [14,'dias','Passando para saber se o momento mudou e se vale retomarmos nossa conversa.'],
  [21,'dias','Tenho uma atualização que pode ajudar no objetivo que conversamos. Quer que eu te conte?'],
  [30,'dias','Último contato por agora, {nome}. Quando for o melhor momento, estou à disposição para retomar.']
];
if(state.manualCadenceVersion!==1){state.manualCadenceVersion=1;state.cadence=[{id:'manual-call',delay:0,unit:'hora',action:'Ligar',text:'Ligação de descoberta obrigatória antes de qualquer mensagem.'},...manualMessageSteps.map((step,index)=>({id:`manual-${index+1}`,delay:step[0],unit:step[1],action:'Mensagem manual',text:step[2]}))];state.manualApprovals=state.manualApprovals||[];persist()}

function manualWhatsappUrl(item,text){let digits=String(item.phone||'').replace(/\D/g,'');if((digits.length===10||digits.length===11)&&!digits.startsWith('55'))digits='55'+digits;return `https://wa.me/${digits}?text=${encodeURIComponent(text)}`}
const localSendMessage=sendMessage;
sendMessage=async function(event){event.preventDefault();const input=document.querySelector('#message-input'),text=input?.value.trim(),item=lead();if(!text||!item)return;if(!item.callDone){toast('Registre a ligação antes de preparar a mensagem.');return}if(state.officialWhatsappConnected){try{await whatsappCall('send',{method:'POST',body:JSON.stringify({organization_id:activeOrganizationId(),to:item.phone.replace(/\D/g,''),text})});toast('Mensagem autorizada e enviada pela API oficial.')}catch(error){toast(error.message);return}}else{window.open(manualWhatsappUrl(item,text),'_blank','noopener');toast('Envio autorizado. O WhatsApp foi aberto com a mensagem pronta.')}item.messages.push(['out',text,now()]);item.last=text;item.lastAt='agora';state.manualApprovals=state.manualApprovals||[];state.manualApprovals.unshift({leadId:item.id,text,approvedAt:new Date().toISOString(),seller:state.user.email});input.value='';persist();render()};

const manualConversation=conversation;
conversation=function(){const html=manualConversation(),item=lead();if(!item)return html;const sequence=`<section class="tip-card manual-sequence"><h3>✓ Fluxo manual de 10 mensagens</h3><p>Nada é disparado sozinho. Escolha uma etapa, revise e clique em Enviar para abrir o WhatsApp.</p><div class="manual-step-list">${manualMessageSteps.map((step,index)=>`<button data-manual-message="${index}"><b>${index+1}</b><span>${step[0]} ${step[1]}</span></button>`).join('')}</div></section>`;return html.replace('<section class="tip-card"><h3>Próximo passo sugerido</h3>',sequence+'<section class="tip-card"><h3>Próximo passo sugerido</h3>')};

const manualBind=bind;
bind=function(){manualBind();document.querySelectorAll('[data-manual-message]').forEach(button=>button.onclick=()=>{const item=lead(),step=manualMessageSteps[Number(button.dataset.manualMessage)],input=document.querySelector('#message-input');if(input){input.value=step[2].replaceAll('{nome}',item.name.split(' ')[0]);input.focus();toast(`Mensagem ${Number(button.dataset.manualMessage)+1} pronta para sua aprovação.`)}});document.querySelectorAll('.connect[data-integration="whatsapp"]').forEach(button=>button.onclick=()=>modal('whatsapp-official'))};

const manualAgenda=reminders;
reminders=function(){const html=manualAgenda();if(state.plan!=='Base')return html;return html.replace('<div class="agenda-tabs">',`<div class="manual-mode-note"><b>Modo manual seguro</b><span>11 etapas: 1 ligação obrigatória + 10 mensagens. Cada envio depende de um clique do vendedor.</span></div><div class="agenda-tabs">`)};

function activeOrganizationId(){return state.support?.active?state.support.orgId:state.user?.organization_id}
async function whatsappCall(action,options={}){const response=await fetch(`/api/whatsapp?action=${action}`,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options}),value=await response.json();if(!response.ok)throw new Error(value.error||'WhatsApp indisponível.');return value}
const officialModal=modal;
modal=function(type,data={}){if(type!=='whatsapp-official')return officialModal(type,data);app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal modal-wide"><h2>WhatsApp oficial</h2><p>Conecte a Cloud API da Meta. As credenciais ficam criptografadas e isoladas nesta empresa.</p><form id="official-whatsapp-form"><div class="config-section compact-fields"><div class="field"><label>Phone Number ID</label><input name="phone_number_id" required></div><div class="field"><label>WhatsApp Business Account ID</label><input name="waba_id"></div><div class="field"><label>Número comercial</label><input name="business_number" placeholder="5511999999999"></div><div class="field"><label>Versão da Graph API</label><input name="graph_version" value="v23.0" required></div></div><div class="field"><label>Token permanente da Meta</label><input name="access_token" type="password" required autocomplete="off"></div><div class="field"><label>App Secret</label><input name="app_secret" type="password" required autocomplete="off"></div><div class="field"><label>Token de verificação do webhook</label><input name="verify_token" type="password" required autocomplete="off"><small class="field-help">Crie uma frase longa e use a mesma ao configurar o webhook na Meta.</small></div><div class="modal-actions"><button type="button" class="btn btn-ghost close-modal">Cancelar</button><button class="btn btn-primary">Salvar conexão oficial</button></div></form></section></div>`);bindModal();document.querySelector('#official-whatsapp-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('.btn-primary'),values=Object.fromEntries(new FormData(event.currentTarget));button.disabled=true;button.textContent='Conectando...';try{const result=await whatsappCall('connect',{method:'POST',body:JSON.stringify({...values,organization_id:activeOrganizationId()})});state.officialWhatsappConnected=true;persist();document.querySelector('#modal')?.remove();render();toast('WhatsApp oficial preparado. Copie o webhook para a Meta.');navigator.clipboard?.writeText(result.webhook_url)}catch(error){button.disabled=false;button.textContent='Salvar conexão oficial';toast(error.message)}})};

async function syncOfficialMessages(){if(!state.logged||!activeOrganizationId())return;try{const connection=await whatsappCall(`connection&organization_id=${encodeURIComponent(activeOrganizationId())}`);state.officialWhatsappConnected=connection.connected;if(!connection.connected)return;const data=await whatsappCall(`messages&organization_id=${encodeURIComponent(activeOrganizationId())}`);state.whatsappImported=state.whatsappImported||[];for(const message of [...data.messages].reverse()){if(state.whatsappImported.includes(message.wa_message_id))continue;let item=state.leads.find(current=>current.phone.replace(/\D/g,'').endsWith(String(message.contact_phone).slice(-10)));if(!item&&message.direction==='in'){item={id:uid(),name:message.contact_name||message.contact_phone,phone:message.contact_phone,origin:'WhatsApp',interest:'Média',niche:'Não informado',revenue:'Não informado',stage:'new',entered:Date.now(),last:'',lastAt:'agora',status:'Novo',discardReason:'',callDone:false,notes:'Contato sincronizado pela API oficial.',messages:[]};state.leads.unshift(item)}if(item){item.messages.push([message.direction,message.body,new Date(message.occurred_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})]);item.last=message.body;item.lastAt='agora'}state.whatsappImported.push(message.wa_message_id)}if(state.whatsappImported.length>2000)state.whatsappImported=state.whatsappImported.slice(-2000);persist()}catch(error){state.officialWhatsappConnected=false}}
if(state.logged){syncOfficialMessages();setInterval(syncOfficialMessages,30000)}
const tenantLeadLookup=lead;
lead=function(id=selectedId){return state.leads.find(item=>item.id===id)||state.leads[0]}
const tenantSafeConversation=conversation;
conversation=function(){if(!state.leads.length)return shell(`<div class="page"><div class="empty-state"><h1>Nenhuma conversa ainda</h1><p>Adicione seu primeiro lead para preparar a ligação e o fluxo manual de dez mensagens.</p><button class="btn btn-primary" data-modal="lead">＋ Adicionar lead</button></div></div>`,'Conversas');return tenantSafeConversation()};
if(state.logged)render();
